43	void
44	testSlerp (const Quatf q1, const Quatf q2, int m, int n)
45	{
46	    //
47	    // For two quaternions, q1 and q2, and the identity quaternion, qi,
48	    //
49	    //     slerp (q1, q2, f) == q1 * slerp (qi, q1.inverse() * q2, f);  (1)
50	    //
51	    // In addition, for integers m and n, with m >= 0, n > 0,
52	    //
53	    //     pow (slerp (qi, q3, m/n), n) == pow (q3, m)                  (2)
54	    //
55	    // This allows us to test if slerp (q1, q2, m/n) works correctly.
56	    // Thanks to Dan Piponi for pointing this out.
57	    //
58	    // Note that e2, our upper bound for the numerical error in (2) is
59	    // fairly large.  The reason for this is that testSlerp() will be
60	    // called with m and n up to 16.  Taking quaternions to the 16th
61	    // power amplifies any inaccuracies.
62	    //
63	
64	    Quatf qi;
65	    Quatf q3   = q1.inverse () * q2;
66	    Quatf q1q2 = slerp (q1, q2, float (m) / float (n));
67	    Quatf qiq3 = slerp (qi, q3, float (m) / float (n));
68	    float e1   = 60 * std::numeric_limits<float>::epsilon ();
69	    float e2   = 600 * std::numeric_limits<float>::epsilon ();
70	
71	    compareQuats (q1q2, q1 * qiq3, e1);
72	    compareQuats (pow (qiq3, n), pow (q3, m), e2);
73	}
74	
75	void
76	testSlerp (const Quatf q1, const Quatf q2)
77	{
78	    const int n = 16;
79	
80	    for (int m = 0; m <= n; ++m)
81	        testSlerp (q1, q2, m, n);
82	}
